#include "conv_transposed_2d_asymmetric_input_asymmetric_kernel_custom_tiling.h"
#include "register/op_def_registry.h"

namespace optiling {
const uint32_t BLOCK_DIM = 8;
const uint32_t TILE_NUM = 8;

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    ConvTransposed2dAsymmetricInputAsymmetricKernelCustomTilingData tiling;

    // 输入 x: [N, Cin, H, W]
    auto x_shape = context->GetInputShape(0)->GetOriginShape();
    uint64_t N   = (x_shape.GetDimNum() > 0) ? x_shape.GetDim(0) : 1;
    uint64_t Cin = (x_shape.GetDimNum() > 1) ? x_shape.GetDim(1) : 1;
    uint64_t H   = (x_shape.GetDimNum() > 2) ? x_shape.GetDim(2) : 1;
    uint64_t W   = (x_shape.GetDimNum() > 3) ? x_shape.GetDim(3) : 1;

    // 权重 w: [Cin, Cout, kH, kW]（符合 PyTorch ConvTranspose2d 的权重格式）
    auto w_shape = context->GetInputShape(1)->GetOriginShape();
    uint64_t wCin = (w_shape.GetDimNum() > 0) ? w_shape.GetDim(0) : 1;
    uint64_t Cout = (w_shape.GetDimNum() > 1) ? w_shape.GetDim(1) : 1;
    uint64_t kH   = (w_shape.GetDimNum() > 2) ? w_shape.GetDim(2) : 1;
    uint64_t kW   = (w_shape.GetDimNum() > 3) ? w_shape.GetDim(3) : 1;

    // 仅支持 stride=(1,1), padding=(0,0), dilation=(1,1), output_padding=(0,0), groups=1
    // 输出尺寸（转置卷积，full 模式）：Hout = H + kH - 1, Wout = W + kW - 1
    uint64_t Hout = H + kH - 1;
    uint64_t Wout = W + kW - 1;

    uint64_t totalLength64 = N * Cout * Hout * Wout;

    context->SetBlockDim(BLOCK_DIM);

    tiling.set_N(static_cast<uint32_t>(N));
    tiling.set_Cin(static_cast<uint32_t>(Cin));
    tiling.set_Cout(static_cast<uint32_t>(Cout));
    tiling.set_H(static_cast<uint32_t>(H));
    tiling.set_W(static_cast<uint32_t>(W));
    tiling.set_kH(static_cast<uint32_t>(kH));
    tiling.set_kW(static_cast<uint32_t>(kW));
    tiling.set_Hout(static_cast<uint32_t>(Hout));
    tiling.set_Wout(static_cast<uint32_t>(Wout));
    tiling.set_totalLength(static_cast<uint32_t>(totalLength64));
    tiling.set_tileNum(TILE_NUM);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    const gert::Shape* x_shape = context->GetInputShape(0); // [N, Cin, H, W]
    const gert::Shape* w_shape = context->GetInputShape(1); // [Cin, Cout, kH, kW]
    if (x_shape->GetDimNum() != 4 || w_shape->GetDimNum() != 4) {
        return ge::GRAPH_FAILED;
    }
    int64_t N   = x_shape->GetDim(0);
    int64_t Cin = x_shape->GetDim(1);
    int64_t H   = x_shape->GetDim(2);
    int64_t W   = x_shape->GetDim(3);

    int64_t wCin = w_shape->GetDim(0);
    int64_t Cout = w_shape->GetDim(1);
    int64_t kH   = w_shape->GetDim(2);
    int64_t kW   = w_shape->GetDim(3);

    if (wCin != Cin) {
        return ge::GRAPH_FAILED;
    }

    // 仅支持 stride=1, padding=0, dilation=1, output_padding=0
    int64_t Hout = H + kH - 1;
    int64_t Wout = W + kW - 1;

    gert::Shape* y_shape = context->GetOutputShape(0);
    y_shape->SetDimNum(4);
    y_shape->SetDim(0, N);
    y_shape->SetDim(1, Cout);
    y_shape->SetDim(2, Hout);
    y_shape->SetDim(3, Wout);
    return GRAPH_SUCCESS;
}

static ge::graphStatus InferDataType(gert::InferDataTypeContext *context)
{
    const auto inputDataType = context->GetInputDataType(0);
    context->SetOutputDataType(0, inputDataType);
    return ge::GRAPH_SUCCESS;
}
}

