import torch
import torch_npu
import custom_ops_lib

class ModelNew(torch.nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1), padding: tuple = (0, 0), output_padding: tuple = (0, 0), dilation: tuple = (1, 1), groups: int = 1, bias: bool = False):
        super().__init__()
        # 仍保留原始模块以获取权重，forward 中调用自定义算子
        self.conv_transpose2d = torch.nn.ConvTranspose2d(
            in_channels, out_channels, kernel_size,
            stride=stride, padding=padding, output_padding=output_padding,
            dilation=dilation, groups=groups, bias=bias
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # 仅支持：stride=(1,1), padding=(0,0), dilation=(1,1), output_padding=(0,0), groups=1, bias=False
        assert self.conv_transpose2d.stride == (1, 1), "Only stride=(1,1) is supported"
        assert self.conv_transpose2d.padding == (0, 0), "Only padding=(0,0) is supported"
        assert self.conv_transpose2d.dilation == (1, 1), "Only dilation=(1,1) is supported"
        assert self.conv_transpose2d.output_padding == (0, 0), "Only output_padding=(0,0) is supported"
        assert self.conv_transpose2d.groups == 1, "Only groups=1 is supported"
        assert self.conv_transpose2d.bias is None, "bias is not supported"
        return custom_ops_lib.conv_transposed_2d_asymmetric_input_asymmetric_kernel_custom(x, self.conv_transpose2d.weight)
